#!/usr/bin/env python3
"""Validate project_kickoff.ics without the optional icalendar library."""
import datetime as dt
import re
import sys

PATH = "project_kickoff.ics"

errors = []

with open(PATH, "r", encoding="utf-8", newline="") as f:
    raw = f.read()

# 1. CRLF line endings (RFC 5545 requirement)
if "\r\n" not in raw:
    errors.append("File does not use CRLF line endings")
lines = raw.split("\r\n")
if lines[-1] != "":
    errors.append("File does not end with a blank line after final CRLF")

# 2. Balanced BEGIN/END blocks
stack = []
for ln in lines:
    if not ln:
        continue
    if ln.startswith("BEGIN:"):
        stack.append(ln[6:])
    elif ln.startswith("END:"):
        name = ln[4:]
        if not stack or stack[-1] != name:
            errors.append(f"Mismatched END:{name}")
            break
        stack.pop()
if stack:
    errors.append(f"Unclosed blocks: {stack}")

# 3. Required top-level fields
joined = "\n".join(lines)
for req in ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:", "CALSCALE:GREGORIAN",
            "BEGIN:VEVENT", "UID:", "DTSTAMP:", "DTSTART", "DTEND",
            "SUMMARY:Project Kickoff Meeting", "END:VEVENT", "END:VCALENDAR"]:
    if req not in joined:
        errors.append(f"Missing required field: {req}")

# 4. DTSTAMP / UID format
m = re.search(r"^DTSTAMP:(\d{8}T\d{6}Z)$", joined, re.M)
if not m:
    errors.append("DTSTAMP not in UTC basic format YYYYMMDDTHHMMSSZ")
else:
    dt.datetime.strptime(m.group(1), "%Y%m%dT%H%M%SZ")  # raises if invalid
uid_m = re.search(r"^UID:(.+)$", joined, re.M)
if not uid_m or "@" not in uid_m.group(1):
    errors.append("UID missing or malformed")

# 5. DTSTART/DTEND ordering and format
start_m = re.search(r"^DTSTART;TZID=([^:]+):(\d{8}T\d{6})$", joined, re.M)
end_m = re.search(r"^DTEND;TZID=([^:]+):(\d{8}T\d{6})$", joined, re.M)
if not start_m or not end_m:
    errors.append("DTSTART/DTEND must use TZID=... with local basic format")
else:
    if start_m.group(1) != end_m.group(1):
        errors.append("DTSTART and DTEND timezones differ")
    s = dt.datetime.strptime(start_m.group(2), "%Y%m%dT%H%M%S")
    e = dt.datetime.strptime(end_m.group(2), "%Y%m%dT%H%M%S")
    if e - s != dt.timedelta(hours=2):
        errors.append(f"Duration is {e - s}, expected 2:00:00")
    if e <= s:
        errors.append("DTEND not after DTSTART")

# 6. VALARM structure
if "BEGIN:VALARM" not in joined or "END:VALARM" not in joined:
    errors.append("Missing VALARM reminder block")
else:
    for req in ["ACTION:DISPLAY", "TRIGGER:-PT15M"]:
        if req not in joined:
            errors.append(f"VALARM missing {req}")

# 7. SUMMARY value sanity
if "SUMMARY:Project Kickoff Meeting" not in joined:
    errors.append("SUMMARY value unexpected")

if errors:
    print("VALIDATION FAILED:")
    for err in errors:
        print(f"  - {err}")
    sys.exit(1)
print("VALIDATION=OK")
print(f"Start: {start_m.group(2)} ({start_m.group(1)})")
print(f"End:   {end_m.group(2)} ({end_m.group(1)})")

